'use strict';
// Proposed interfaces only. All records, requirements and interactions are illustrative.
// No production APIs, analytics, auth, mail, payment or policy services are called.
const $=id=>document.getElementById(id),h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={box:'M3 7l9-4 9 4-9 4-9-4zm0 0v10l9 4 9-4V7M12 11v10',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',file:'M14 2H5v20h14V7l-5-5zm0 0v6h5M8 12h8M8 16h8',check:'M4 12l5 5L20 6',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3z',flask:'M9 3h6M10 3v7L5 19v2h14v-2l-5-9V3M8 15h8',globe:'M21 12A9 9 0 113 12a9 9 0 0118 0zM3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18z',users:'M16 21v-3c0-3-8-3-8 0v3M12 3a4 4 0 110 8 4 4 0 010-8zM20 13v6M17 16h6',mail:'M3 5h18v14H3zM3 5l9 8 9-8',settings:'M4 5h16M4 12h16M4 19h16M9 2v6M16 9v6M8 16v6',arrow:'M4 12h16M14 6l6 6-6 6',upload:'M12 16V3M7 8l5-5 5 5M4 15v6h16v-6',search:'M10 3a7 7 0 110 14 7 7 0 010-14zM15 15l6 6',clock:'M12 3a9 9 0 110 18 9 9 0 010-18zM12 7v5l4 2',message:'M3 4h18v13H9l-6 4V4z',link:'M10 14l4-4M8 16l-2 2a4 4 0 01-6-6l5-5M16 8l2-2a4 4 0 016 6l-5 5'};
const icon=(name='box')=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.box}"/></svg>`;
const V=[
 ['overview','Registry overview','Merchant','Core proposal','A product registry, before a report library.','The landing page is organized around registered products, incomplete product facts, policy assessments and merchant tasks. MyCOA appears as one evidence capability.', ['Registry enrollment is separate from product readiness.','The next action comes from a product task, not a generic COA upload.','A no-COA company still gets a complete, useful workspace.'],'Confirm overview metrics and the name Q-Registry.'],
 ['processor','Processor merchant workspace','Processor','Core proposal','Separate enrollment from product and evidence readiness.','The processor sees invitation, portal, Registry access and assessment tasks as different columns.', ['No MyCOA Active badge doubles as a compliance decision.','COA needs are product-specific evidence tasks.','Open a merchant or prepare a Registry invitation.'],'Confirm the processor status vocabulary and permitted merchant projection.'],
 ['invite-compose','Q-Registry invitation composer','Processor','Core proposal','Invite to the registry, with the right evidence tools.','The composer introduces Registry enrollment, the existing commercial offer and MyCOA as an included lab-evidence tool.', ['Review recipient/account state before sending.','No blanket “COA merchant” assumption.','The invitation preview leads to the proposed Registry email.'],'Confirm system and customer-authored invitation copy; preserve identity and delivery semantics.'],
 ['invite-email','Merchant invitation email','Merchant','Core proposal','The invitation explains why a non-COA merchant should join.','Q-Registry is the headline. Products, policies and evidence lead; MyCOA is explained as a tool for lab reports where needed.', ['One invitation to the broader product.','Existing-account and company context remain explicit.','The next step is the existing offer, not an obligatory COA wizard.'],'Brian must approve naming and invitation wording.'],
 ['offer','Registry offer & capabilities','Merchant','Core proposal','Sell Registry access, with a clear capability breakdown.','The offer makes the product catalog, assessments and evidence tasks the base experience. MyCOA appears inside the included capability list.', ['The pictured $199 monthly amount is the existing illustrative offer, not new pricing.','No COA upload prerequisite for access.','Do not gate minimum required-evidence remediation behind premium tools.'],'Confirm packaging, grandfathering, included tools and required/optional offer rules.'],
 ['onboarding','Product-first onboarding','Merchant','Core proposal','Start with products, however much the merchant has today.','The first-run screen offers adding a product, importing a catalog, scanning a website or returning later.', ['No COA upload checklist.','A prelaunch company can enter an empty registry.','Reports are added later to the products that need them.'],'Confirm catalog readiness and onboarding completion rules.'],
 ['products','Registry product catalog','Merchant','Core proposal','Products are the organizing unit.','The catalog leads with product identity, classification, assessment and evidence tasks. A COA is no longer a universal primary column.', ['Separate registration, assessment and publication.','Unknown applicability is visible as a classification task.','Use the scenario control to compare four merchant catalogs.'],'Resolve the real backend unknown-versus-exempt contract before implementation.'],
 ['product','Product registry record','Merchant','Core proposal','A product record works with or without a COA.','The new detail screen collects product facts, applicable policies, required evidence and publication in one place.', ['Policy obligations are scoped to the product.','MyCOA is a linked tool inside evidence, not the product identity.','A missing COA does not stop the merchant maintaining product facts.'],'Confirm product/variant/website scope and allowed edits.'],
 ['assessments','Product policy assessments','Merchant','Core proposal','Show the assessment and the reason, not a blanket compliance badge.','Merchants see scoped policy rows, missing inputs, review states and the next action. Example policy titles here are illustrative, not legal requirements.', ['Not evaluated, Needs information and Needs review remain separate.','The existing policy engine remains authoritative.','No fictional PASS or shipping clearance is shown.'],'Policy owners define applicability, evidence and permitted explanations.'],
 ['evidence','Product evidence hub','Merchant','Core proposal','One evidence workspace, with MyCOA inside it.','Labels, documents, product facts and lab reports are organized by the task they resolve. The lab library is a secondary capability.', ['Filter by evidence type and required task.','Attach a required lab report even with premium MyCOA tools disabled.','Receiving a file does not manufacture an assessment result.'],'Agree Core remediation access versus premium library/management capabilities.'],
 ['mycoa','MyCOA lab-evidence feature','Merchant','Core proposal','Keep the recognizable lab tool as a component of Registry.','MyCOA sits under Evidence. Its library, matching and report history support products that use lab evidence.', ['Global navigation and product name remain Q-Registry.','No lab evidence needed is a normal state.','Optional library tools do not gate the rest of the registry.'],'Confirm MyCOA packaging while preserving existing entitled lab tools.'],
 ['requests','Merchant tasks & information requests','Merchant','Core proposal','Turn findings into specific product actions.','The merchant sees requests for product facts, missing evidence and processor review in a consistent task list.', ['Tasks identify the product and requested information.','Case discussions stay separate from public results.','A submitted response goes to review; it is not automatically approved.'],'Confirm which processor information and decisions are projected to merchants.'],
 ['sharing','Product publication workspace','Merchant','Later release','Make publication product-first and deliberate.','Choose an authorized product, public fields and evidence independently from internal registration. Existing certificate sharing stays a separate mode.', ['A record can have zero COAs.','Preview before publishing; public-safe states stay truthful.','The prototype changes only its own in-memory demonstration state.'],'Define publication authority, adverse/incomplete-state rules and revocation.'],
 ['stamp','Product stamp & embed','Merchant','Later release','A product stamp links to the product record.','Q-Registered identifies registration; the linked product record separately discloses assessment status. The existing View COAs button stays available.', ['Select the exact product and website.','Registration mark is not “certified” or “allowed to ship.”','New product mode does not replace installed certificate snippets.'],'Approve mark meaning, product/variant matching, old URL compatibility and freshness.'],
 ['public','Public product record','Public','Later release','Show a truthful product record without requiring a COA.','The public view separates registered identity, disclosed policy assessment and optional published evidence.', ['No report is needed to identify a registered product.','Incomplete/unknown results are disclosed, not turned green.','The page contains illustrative data and is not a real public registration.'],'Approve public claims, result scope/date and visibility/revocation behavior.'],
 ['subscription','Registry subscription & features','Merchant','Core proposal','Make the commercial relationship match the product.','Subscription is Q-Registry. The included capabilities list makes MyCOA one part of the plan.', ['Preserve existing prices, dates, IDs and sponsor/trial treatment.','Registry enrollment is independent from a product assessment.','No new add-on price is proposed here.'],'Commercial owners approve package mapping and grandfathering.'],
 ['capabilities','Registry / MyCOA capability model','Team','Packaging proposal','Design the commercial gate without blocking remediation.','Review what Registry Core provides and which advanced tools are packaged as MyCOA. Toggle MyCOA tools to see that Products and required-evidence submission remain usable.', ['Core: catalog, product tasks, policy display and authorized required-evidence submission.','MyCOA: broader lab library, matching and report management.','Public record/stamps and shipping remain later capabilities.'],'This is a proposal configurator, not Q-Config. Final commercial mapping still requires approval.'],
 ['shipping','Product shipping information','Merchant','Future concept','Assess a destination explicitly, later.','A proposed future screen collects product, destination and policy context. It displays Not assessed until an authoritative assessment exists.', ['No shipping permission derives from registration or COA presence.','Policy engine and commerce integration need separate specifications.','This prototype does not evaluate destinations or enforce checkout.'],'Separate shipping scope, policy/content ownership, integrations and real enforcement acceptance.']
].map(([id,title,actor,phase,headline,summary,points,decision])=>({id,title,actor,phase,headline,summary,points,decision}));
const baseProducts={
 soap:{id:'soap',name:'Plant-based soap bar',sku:'SOAP-001',category:'Personal care',coa:'not-required',status:'Needs information',reason:'Add the product label',description:'Plant-based soap bar for everyday use.',site:'everyday.example.test',type:'Label',task:'Product label'},
 jar:{id:'jar',name:'Ceramic storage jar',sku:'HOME-014',category:'Household goods',coa:'not-required',status:'Not evaluated',reason:'Ready for a policy assessment',description:'Refillable ceramic storage jar.',site:'everyday.example.test',type:'Product facts',task:'Product information review'},
 extract:{id:'extract',name:'Botanical extract',sku:'BOT-042',category:'Botanical product',coa:'required',status:'Needs information',reason:'A lab report is requested',description:'Botanical extract product; evidence review pending.',site:'botanical.example.test',type:'COA',task:'Required lab report'},
 tincture:{id:'tincture',name:'Botanical tincture',sku:'BOT-016',category:'Botanical product',coa:'required',status:'Needs information',reason:'A lab report is requested',description:'Botanical tincture; evidence review pending.',site:'botanical.example.test',type:'COA',task:'Required lab report'},
 unknown:{id:'unknown',name:'New product',sku:'NEW-003',category:'Not classified',coa:'unknown',status:'Needs review',reason:'Confirm product classification',description:'Product facts need classification before evidence applicability is determined.',site:'everyday.example.test',type:'Classification',task:'Confirm classification'}
};
const state={screen:'overview',scenario:'mixed',tools:'included',selected:'soap',notes:false,filter:'all',query:'',uploads:{},extras:{mixed:[],'no-coa':[],required:[],empty:[]},published:{},responses:{},catalogMethod:'add',draftRecipient:'merchant@preview.example.test',destination:'',stampStyle:'full'};
const products=()=>[...({mixed:['soap','extract','unknown'],'no-coa':['soap','jar'],required:['extract','tincture'],empty:[]}[state.scenario].map(k=>baseProducts[k])),...state.extras[state.scenario]];
const current=()=>products().find(p=>p.id===state.selected)||products()[0];
const company=()=>({mixed:'Preview Goods Co.','no-coa':'Everyday Goods Co.',required:'Botanical Goods Co.',empty:'New Merchant Co.'}[state.scenario]);
const pill=(text,color='')=>`<span class="pill ${color}">${h(text)}</span>`;
const status=(p)=>state.uploads[p.id]?pill('Needs review','purple'):pill(p.status,p.status==='Needs information'?'amber':p.status==='Needs review'?'purple':'');
const coaLabel=p=>p.coa==='required'?'Lab report requested':p.coa==='unknown'?'Applicability not determined':'No lab report required';
const button=(text,action,cls='',attrs='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const link=(text,screen,cls='',extra='')=>`<a href="#screen=${screen}&scenario=${state.scenario}" data-go="${screen}" class="${cls}" ${extra}>${text}</a>`;
const hero=(title,description,actions='')=>`<div class="page-head"><div><h1>${title}</h1><p>${description}</p></div><div class="page-actions">${actions}</div></div>`;
const card=(title,body,subtitle='',action='')=>`<section class="card"><div class="card-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>${body}</section>`;
const empty=()=>`<section class="card empty-state"><div class="registry-glyph">${icon('box')}</div><span class="overline">Your product registry</span><h2>Start with your first product</h2><p>Register your product facts now. Add labels, documents or lab reports later, when an applicable policy asks for them.</p>${button('Add a product','add-product','primary')} ${button('Import a catalog','import-catalog')}<p class="note-inline">No COA upload is required to create your catalog.</p></section>`;
function navItem(name,target,ico,sub=false){const active=state.screen===target||target==='product'&&['assessments'].includes(state.screen);return link((sub?'':icon(ico))+'<span>'+name+'</span>',target,'nav-link'+(sub?' sub':'')+(active?' active':''));}
function shell(body){const role=V.find(v=>v.id===state.screen).actor,processor=role==='Processor';const nav=`<div class="sidebar"><div class="qredible-logo">Q<span>redible</span></div><div class="nav-label">${processor?'PROCESSOR WORKSPACE':'MY BUSINESS'}</div><button class="nav-link" data-action="company">${icon('users')}<span>Company</span></button>${processor?navItem('We Monitor','processor','grid'):navItem('Compliance Cases','requests','message')}<div class="nav-link active registry-item">${icon('box')}<strong>Q-Registry</strong></div><div class="subnav">${navItem('Overview','overview','',true)}${navItem('Products','products','',true)}${navItem('Policy assessments','assessments','',true)}${navItem('Evidence','evidence','',true)}${navItem('Tasks & requests','requests','',true)}${navItem('Public sharing','sharing','',true)}</div><div class="nav-label">WORKSPACE</div>${navItem('Subscription & features','subscription','settings')}${processor?navItem('Invitations','invite-compose','mail'):''}<div class="nav-spacer"></div><button class="nav-link" data-action="info">${icon('message')}<span>Support</span></button></div>`;
return `<div class="app-shell">${nav}<div class="app-main"><div class="appbar"><div class="workspace-name">Q-Registry</div><div class="askq">⌕ &nbsp; Ask-Q… <span class="tiny">&nbsp; Ctrl K</span></div><div class="account"><span class="merchant-name">${processor?'Preview Processing Co.':h(company())}</span><span class="subtle">⌄</span><span class="avatar">${processor?'PP':'PG'}</span></div></div><div class="content">${body}</div></div></div>`;}
function productRows(){const items=products().filter(p=>(!state.query||p.name.toLowerCase().includes(state.query.toLowerCase()))&&(state.filter==='all'||(state.filter==='required'&&p.coa==='required')||(state.filter==='unknown'&&p.coa==='unknown')));return `<div class="table-wrap"><table><thead><tr><th>PRODUCT</th><th>CLASSIFICATION</th><th>ASSESSMENT</th><th>NEXT ACTION</th><th>PUBLIC RECORD</th><th></th></tr></thead><tbody>${items.map(p=>`<tr><td><div class="row"><div class="product-icon">${icon('box')}</div><div>${link(h(p.name),'product','product-link',`data-product="${h(p.id)}"`)}<p>${h(p.sku)} · Registered</p></div></div></td><td>${h(p.category)}<p>${p.coa==='unknown'?'Needs classification':'Product facts recorded'}</p></td><td>${status(p)}<p>Product-level assessment</p></td><td>${h(state.uploads[p.id]?'Evidence received · review pending':p.reason)}<p>${h(coaLabel(p))}</p></td><td>${pill(state.published[p.id]?'Published':'Private',state.published[p.id]?'blue':'')}</td><td>${link('Open →','product','small',`data-product="${h(p.id)}"`)}</td></tr>`).join('')||'<tr><td colspan="6">No products match this view.</td></tr>'}</tbody></table></div><div class="table-foot"><span>${items.length} products · ${company()}</span><span>1</span></div>`;}
function taskRows(){return products().map(p=>`<div class="task"><div class="task-icon">${icon(p.type==='COA'?'flask':p.type==='Classification'?'search':'file')}</div><div><h3>${h(state.uploads[p.id]?'Review received evidence':p.task)}</h3><p>${h(p.name)} · ${h(state.uploads[p.id]?'Submitted for review':p.reason)}</p></div>${button('Review','product-task','',`data-product="${h(p.id)}"`)}</div>`).join('');}
function overview(){const ps=products();return hero('Your product registry','Manage your products, review applicable policies and keep the right evidence connected.',button('Add a product','add-product','primary'))+`<div class="summary-banner"><div><span class="overline">Q-Registry · ${h(company())}</span><h2>${ps.length?'A home for every product you sell.':'Your registry is ready when you are.'}</h2><p>Start with your catalog. Policy assessments identify what information is needed; MyCOA connects lab reports for products that use them.</p></div><div class="registry-glyph">${icon('box')}</div></div><div class="stats"><div class="stat"><span class="label">Registered products</span><strong>${ps.length}</strong><small>Product records in your catalog</small></div><div class="stat"><span class="label">Need information</span><strong>${ps.filter(p=>p.status==='Needs information'&&!state.uploads[p.id]).length}</strong><small>Product facts or evidence to provide</small></div><div class="stat"><span class="label">Need review</span><strong>${ps.filter(p=>p.status==='Needs review'||state.uploads[p.id]).length}</strong><small>Classification or assessment review</small></div><div class="stat"><span class="label">Public records</span><strong>${ps.filter(p=>state.published[p.id]).length}</strong><small>Explicitly shared product records</small></div></div>${ps.length?`<div class="grid main-side">${card('Your next steps',taskRows(),'Product-specific actions, in one place',link('View all tasks →','requests','small'))}<div class="stack">${card('Registry access',`<div class="card-pad"><div class="row between"><strong class="small">Q-Registry membership</strong>${pill('Active','blue')}</div><p class="small subtle space-top">Your subscription gives your team access. Each product keeps its own assessment and publication state.</p>${link('View subscription & features →','subscription','small')}</div>`)}${card('Your evidence tools',`<div class="tool-card"><div class="task-icon">${icon('flask')}</div><div><h3>MyCOA</h3><p>Lab reports, matching and report management inside Q-Registry.</p>${pill(state.tools==='included'?'Included capability':'Optional lab tools','purple')}<p>${link('Open MyCOA →','mycoa','small')}</p></div></div>`)} </div></div>`:empty()}<div class="grid two space-top"><div class="card tool-card"><div class="task-icon">${icon('file')}</div><div><h3>Evidence beyond lab reports</h3><p>Product labels, documents and facts support the policies that apply.</p>${link('Go to evidence →','evidence','small')}</div></div><div class="card tool-card"><div class="task-icon">${icon('globe')}</div><div><h3>Control what you share</h3><p>Keep records private, or preview a product-first public experience.</p>${link('Review public sharing →','sharing','small')}</div></div></div>`;}
function catalog(){return hero('Products','Your product records, their assessments and the next action for each one.',button('Import catalog','import-catalog')+button('Add a product','add-product','primary'))+(products().length?`<div class="card"><div class="table-toolbar"><input id="product-search" class="search" aria-label="Search registered products" placeholder="Search your registered products…" value="${h(state.query)}"><select id="product-filter" aria-label="Filter product tasks"><option value="all" ${state.filter==='all'?'selected':''}>All products</option><option value="required" ${state.filter==='required'?'selected':''}>Lab evidence requested</option><option value="unknown" ${state.filter==='unknown'?'selected':''}>Needs classification</option></select>${pill('All websites')}</div>${productRows()}</div><p class="note-inline">Registration keeps a product on record. Assessment and public publication are separate states.</p>`:empty());}
function productHeader(p){return `<div class="breadcrumbs">${link('Q-Registry','overview')} / ${link('Products','products')} / ${h(p.name)}</div>`+hero(h(p.name),h(p.sku)+' · '+h(p.category)+' · '+h(p.site),button('Edit product facts','edit-product')+button('Preview public record','preview-public','primary'))+`<div class="row space-top" style="margin-bottom:20px">${pill('Registered','blue')}${status(p)}${pill(state.published[p.id]?'Public record published':'Private record')}</div>`;}
function product(){const p=current();if(!p)return hero('Product record','Add a product to begin.')+empty();return productHeader(p)+`<div class="tabs"><button class="active" data-go="product">Product facts</button><button data-go="assessments">Policy assessments</button><button data-go="evidence">Required evidence</button><button data-go="sharing">Public sharing</button></div><div class="grid main-side">${card('Product identity',`<div class="card-pad"><div class="facts"><div class="fact"><span>Product name</span><strong>${h(p.name)}</strong></div><div class="fact"><span>SKU</span><strong>${h(p.sku)}</strong></div><div class="fact"><span>Classification</span><strong>${h(p.category)}</strong></div><div class="fact"><span>Website</span><strong>${h(p.site)}</strong></div><div class="fact"><span>Variant scope</span><strong>Parent product</strong></div><div class="fact"><span>Registration</span><strong>Recorded · October 22</strong></div></div><hr class="divider"><p class="small subtle">${h(p.description)}</p></div>`)}<div class="stack"><div class="card card-pad"><h3>What this product needs</h3><div class="status-box ${p.coa==='unknown'?'purple':p.coa==='required'?'warning':''} space-top"><strong>${h(state.uploads[p.id]?'Evidence awaiting review':p.reason)}</strong><p>${p.coa==='unknown'?'Confirm classification before determining evidence applicability.':p.coa==='required'?'A lab report is requested in this example assessment. You can still manage this product while it is missing.':'This example product has no lab-report requirement. Other product information can still be needed.'}</p></div><div class="space-top">${button(p.coa==='unknown'?'Review classification':'Provide requested evidence','product-task','blue',`data-product="${h(p.id)}"`)}</div></div><div class="card card-pad"><h3>Lab evidence</h3><p class="small subtle">${h(coaLabel(p))}</p>${p.coa==='required'?`${link('View report task →','evidence','small')}<hr class="divider"><span class="tiny subtle">MyCOA is your lab-evidence tool within Registry.</span>`:p.coa==='unknown'?pill('Review needed','purple'):`${pill('Not required')}<p class="note-inline">Your product record does not depend on a COA.</p>`}</div></div></div>`;}
function assessments(){const p=current();if(!p)return hero('Policy assessments','Add product facts before reviewing applicable policy assessments.')+empty();return productHeader(p)+hero('Policy assessments','See the scope, missing inputs and next action for this product.')+`<div class="notice">Example assessment display. The policy titles and requirements below are illustrative design data; final applicability comes from the existing published policy engine.</div><div class="card space-top"><div class="table-wrap"><table><thead><tr><th>POLICY / SCOPE</th><th>ASSESSMENT</th><th>WHAT IS NEEDED</th><th>REVIEWED</th><th></th></tr></thead><tbody><tr><td><strong>Product information review</strong><p>Example policy · v1.0 · parent product</p></td><td>${pill(p.coa==='unknown'?'Needs review':'Needs information',p.coa==='unknown'?'purple':'amber')}</td><td>${h(p.coa==='unknown'?'Product classification':'Complete product facts and evidence')}</td><td>Not completed</td><td>${button('Review inputs','edit-product')}</td></tr><tr><td><strong>Product evidence review</strong><p>Example policy · v1.0 · ${h(p.category)}</p></td><td>${status(p)}</td><td>${h(p.coa==='required'?'Lab report':p.coa==='unknown'?'Applicability not determined':'Product label / facts')}</td><td>Not completed</td><td>${button('View evidence','go-evidence')}</td></tr><tr><td><strong>Public assessment disclosure</strong><p>Publication scope and wording</p></td><td>${pill('Not published')}</td><td>Publication authority and approved public fields</td><td>—</td><td>${button('Review sharing','go-sharing')}</td></tr></tbody></table></div></div><div class="grid two space-top"><div class="card card-pad"><h3>Assessment is product-specific</h3><p class="small subtle">Your Registry subscription and the presence of a report are separate from a policy decision. Incomplete inputs stay incomplete.</p></div><div class="card card-pad"><h3>Need to clarify a finding?</h3><p class="small subtle">Ask a question or respond to an information request in your workspace.</p>${link('Open tasks & requests →','requests','small')}</div></div>`;}
function evidence(){const ps=products();return hero('Evidence','Product facts, labels, documents and lab reports—organized around what each product needs.',button('Attach evidence','attach-generic','primary'))+`<div class="tabs"><button class="active">All evidence</button><button data-action="filter-labels">Labels & documents</button><button data-go="mycoa">MyCOA · lab reports</button></div>`+(ps.length?`<div class="card"><div class="card-head"><div><h2>Product evidence tasks</h2><p>Submitting a document does not automatically approve a product.</p></div>${pill('Required & pending')}</div><div class="table-wrap"><table><thead><tr><th>PRODUCT</th><th>REQUESTED INFORMATION</th><th>EVIDENCE STATE</th><th>LAB APPLICABILITY</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td>${link(h(p.name),'product','product-link',`data-product="${h(p.id)}"`)}</td><td>${h(p.task)}<p>${p.type==='COA'?'MyCOA lab evidence':p.type==='Classification'?'Product facts':'Registry evidence'}</p></td><td>${state.uploads[p.id]?pill('Received · review pending','purple'):pill(p.coa==='unknown'?'Needs classification':'Requested','amber')}<p>${h(state.uploads[p.id]||'No evidence submitted')}</p></td><td>${h(coaLabel(p))}</td><td>${button(p.coa==='unknown'?'Add product facts':'Attach evidence',p.coa==='unknown'?'edit-product':'attach-evidence','',`data-product="${h(p.id)}"`)}</td></tr>`).join('')}</tbody></table></div></div>`:empty())+`<div class="card tool-card space-top"><div class="task-icon">${icon('flask')}</div><div><span class="overline">Lab-evidence capability</span><h3>MyCOA</h3><p>Use the report library, match reports to products and manage lab evidence. Required-evidence submission stays available from the product task.</p>${link(state.tools==='included'?'Open MyCOA library →':'Explore MyCOA tools →','mycoa','small')}</div><div style="margin-left:auto">${pill(state.tools==='included'?'Included':'Optional tools','purple')}</div></div>`;}
function mycoa(){const labs=products().filter(p=>p.coa==='required');return `<div class="breadcrumbs">${link('Q-Registry','overview')} / ${link('Evidence','evidence')} / MyCOA</div>`+hero('MyCOA','Your lab-report library and matching tools, inside Q-Registry.',state.tools==='included'?button('Add lab report','attach-generic','primary'):button('Review included features','go-subscription'))+`<div class="notice">${state.tools==='included'?'MyCOA is included in this illustrative Registry plan. Use Products and Evidence for product-specific requirements.':'Advanced MyCOA library tools are not included in this review scenario. Your registry remains usable, and required evidence can still be submitted from a product task.'}</div>`+(state.tools!=='included'?`<div class="card card-pad space-top"><span class="overline">Optional lab tools</span><h2>Manage a connected lab-report library</h2><ul class="check-list"><li>Central report library and history</li><li>Report-to-product matching</li><li>Broader lab-report management</li></ul>${button('Review your Registry features','go-subscription','primary')}<hr class="divider"><p class="small subtle">Need to submit a report that a product assessment requests?</p>${link('Go to required evidence tasks →','evidence','small')}</div>`:labs.length?`<div class="stats"><div class="stat"><span class="label">Reports received</span><strong>${labs.filter(p=>state.uploads[p.id]).length}</strong><small>Not equivalent to approved results</small></div><div class="stat"><span class="label">Products requesting a report</span><strong>${labs.length}</strong><small>Product-specific evidence tasks</small></div><div class="stat"><span class="label">Awaiting review</span><strong>${labs.filter(p=>state.uploads[p.id]).length}</strong><small>Received evidence</small></div><div class="stat"><span class="label">Public reports</span><strong>0</strong><small>Separately controlled</small></div></div>${card('Lab report requests',labs.map(p=>`<div class="task"><div class="task-icon">${icon('flask')}</div><div><h3>${h(p.name)}</h3><p>${h(state.uploads[p.id]||'No lab report on file')}</p></div>${button('Attach report','attach-evidence','',`data-product="${h(p.id)}"`)}</div>`).join(''))}`:`<section class="card empty-state space-top"><div class="registry-glyph">${icon('flask')}</div><h2>No lab reports needed right now</h2><p>Your products can be managed and assessed in Registry without a COA. MyCOA is here when lab evidence is relevant.</p>${button('Back to products','go-products','primary')}</section>`);}
function requests(){return hero('Tasks & information requests','See what is needed, respond in context and follow the review.',button('Ask a question','ask-question'))+(products().length?`<div class="card"><div class="card-head"><h2>Open product tasks</h2>${pill(products().length+' tasks','amber')}</div>${products().map(p=>`<div class="task"><div class="task-icon">${icon('message')}</div><div><h3>${h(p.task)}</h3><p>${h(p.name)} · ${state.responses[p.id]?'Response submitted · awaiting review':'Awaiting your information'}</p></div>${button('Open request','open-request','',`data-product="${h(p.id)}"`)}</div>`).join('')}</div>`:empty());}
function selectedProductControl(id='product-choice'){return `<select id="${id}" aria-label="Select product">${products().map(p=>`<option value="${h(p.id)}" ${current()?.id===p.id?'selected':''}>${h(p.name)}</option>`).join('')}</select>`;}
function sharing(){const p=current();return hero('Public sharing','Choose what customers can see. Internal registration does not publish a product.',button('Preview product record','preview-public','primary'))+`<div class="tabs"><button class="active">Product records <span class="tiny">· proposed</span></button><button data-action="certificate-sharing">MyCOA certificate pages</button></div>`+(!p?empty():`<div class="grid main-side"><div class="stack"><div class="card card-pad"><div class="row between"><div><h2>Product publication</h2><p class="small subtle">Choose the product and approved public fields.</p></div>${pill(state.published[p.id]?'Published in prototype':'Private',state.published[p.id]?'blue':'')}</div><div class="form-stack space-top"><label>Product record ${selectedProductControl()}</label><label class="switch"><input type="checkbox" checked disabled> Product identity and company</label><label class="switch"><input type="checkbox" checked id="share-assessment"> Assessment state, scope and date</label><label class="switch"><input type="checkbox" id="share-coa" ${p.coa==='not-required'?'disabled':''}> Separately authorized published lab reports</label></div><hr class="divider"><div class="status-box"><strong>${h(coaLabel(p))}</strong><p>${p.coa==='not-required'?'A public product record can exist without a lab report.':p.coa==='unknown'?'The public record must keep undetermined applicability visible.':'Only individually authorized reports would be shown; a missing report stays missing.'}</p></div><div class="row space-top">${button(state.published[p.id]?'Withdraw product record':'Review & publish record','publish-product','primary')}${button('Preview','preview-public')}</div></div><div class="card card-pad"><h3>Existing certificate sharing</h3><p class="small subtle">Existing MyCOA storefronts and View COAs buttons keep their certificate-specific publication controls.</p>${button('Review certificate mode','certificate-sharing','text')}</div></div><div class="stack"><div class="card card-pad"><span class="overline">Customer-facing preview</span><h3 style="margin-top:10px">${h(p.name)}</h3><div class="space-top">${stamp()}</div><hr class="divider"><div class="list-line"><span>Registration</span><strong>Product recorded</strong></div><div class="list-line"><span>Assessment</span>${status(p)}</div><div class="list-line"><span>Lab evidence</span><strong>${p.coa==='not-required'?'Not required':p.coa==='unknown'?'Undetermined':'Requested'}</strong></div>${link('Open full product record →','public','small')}</div><div class="card card-pad"><h3>A product-page stamp</h3><p class="small subtle">Link the exact product on your website to its registered product record.</p>${link('Design a Q-Registered stamp →','stamp','small')}</div></div></div>`);}
function stamp(){return `<div class="stamp">${icon('box')}<div>Q-REGISTERED<small>View product record ↗</small></div></div>`;}
function stampPage(){const p=current();return hero('Product stamps & embeds','A product-first link to the record behind the mark.',button('Preview linked record','preview-public','primary'))+(!p?empty():`<div class="grid two"><div class="card card-pad"><h2>Q-Registered product stamp</h2><div class="form-stack space-top"><label>Product ${selectedProductControl()}</label><label>Website <select><option>${h(p.site)}</option></select></label><label>Appearance <select id="stamp-style"><option value="full" ${state.stampStyle==='full'?'selected':''}>Mark with record link</option><option value="compact" ${state.stampStyle==='compact'?'selected':''}>Compact text link</option></select></label></div><hr class="divider"><p class="small subtle">Place the stamp on this product’s page. It identifies registration; the linked record discloses the assessment separately.</p>${button('Copy example snippet','copy-snippet','primary')}</div><div class="stack"><div class="card card-pad"><span class="overline">Stamp preview</span><div style="display:grid;place-items:center;min-height:170px">${state.stampStyle==='full'?stamp():link('Q-Registered · View product record ↗','public','small')}</div><div class="status-box"><strong>${h(p.name)}</strong><p>${h(p.site)} · Product record only</p></div></div><div class="card card-pad"><h3>Example integration</h3><pre class="code" id="embed-snippet">&lt;a href="https://registry.example.test/products/${h(p.id)}"&gt;Q-Registered · View product record&lt;/a&gt;</pre><p class="note-inline">Example endpoint only. This prototype issues no live embed or registration.</p></div></div></div>`);}
function publicRecord(){const p=current();if(!p)return shell(hero('Public product record','Add a product before previewing a public record.')+empty());return `<div class="public-shell"><div class="public-top"><div class="public-brand">Q-Registry <span class="small subtle">/ Product record</span></div>${button('Back to sharing','go-sharing')}</div><div class="notice space-top">${state.published[p.id]?'Prototype publication view':'Unpublished design preview'} · Illustrative product data</div><div class="public-hero"><div class="product-visual">${icon('box')}</div><div><span class="overline">${h(company())}</span><h1>${h(p.name)}</h1><p class="small subtle">${h(p.description)}</p><p class="tiny subtle">Record QREG-${h(p.sku)} · ${h(p.site)}</p></div>${stamp()}</div><div class="grid three"><div class="card card-pad"><span class="overline">Registration</span><h3 style="margin-top:12px">Product recorded</h3><p class="small subtle">The product and company have a registry record.</p></div><div class="card card-pad"><span class="overline">Policy assessment</span><div style="margin:12px 0">${status(p)}</div><p class="small subtle">An assessment is incomplete. Registration does not assert a passing result.</p></div><div class="card card-pad"><span class="overline">Evidence</span><h3 style="margin-top:12px">${p.coa==='not-required'?'No COA required':p.coa==='unknown'?'Applicability under review':'Lab evidence requested'}</h3><p class="small subtle">${p.coa==='not-required'?'A product record does not require a lab report.':'This example record has no public report attached.'}</p></div></div><section class="public-section">${card('Disclosed assessment',`<div class="card-pad"><div class="row between"><div><strong class="small">Example product information review</strong><p class="tiny subtle">Illustrative policy · v1.0 · parent product · assessment not completed</p></div>${status(p)}</div><hr class="divider"><p class="small subtle">${h(p.reason)}. This page identifies a registered product; it does not certify compliance with all regulations or authorize sale or shipment.</p></div>`)}</section><section class="public-section">${card('Published evidence',`<div class="card-pad"><p class="small subtle">No evidence is published in this design example. Product records and the publication of individual documents are separate choices.</p></div>`)}</section><div class="public-footer">Q-Registry by Qredible · Proposed product record · Working mark and wording subject to approval</div></div>`;}
function offer(){return hero('Welcome to Q-Registry','Register and monitor products, with the evidence their policies require.')+`<div class="form-layout"><div><span class="overline">Q-Registry membership</span><h2 style="font-size:31px;letter-spacing:-1px;line-height:1.2;margin:14px 0">Your catalog comes first.<br>Evidence follows the product.</h2><p class="subtle small">One workspace for product records, policy assessments and the information your team needs to provide.</p><div class="stack space-top">${[['box','Product registry','Create and maintain product facts with or without a COA.'],['shield','Policy assessments','See applicable scope, missing information and next actions.'],['file','Evidence & requests','Respond with labels, documents and required lab evidence.'],['flask','MyCOA · lab-evidence feature','Broader report library and management, where included.']].map(([i,t,d])=>`<div class="choice">${icon(i)}<div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</div></div><div class="card card-pad"><span class="overline">Illustrative existing merchant offer</span><h2 style="margin-top:10px">Q-Registry membership</h2><div class="price">$199<small> / month</small></div><p class="tiny subtle">Existing example offer · no new price proposed</p><hr class="divider"><ul class="check-list"><li>Product registry and merchant workspace</li><li>Policy assessment display and tasks</li><li>Authorized required-evidence submission</li><li>MyCOA lab tools ${state.tools==='included'?'included':'not included in this scenario'}</li></ul><label class="switch"><input id="offer-consent" type="checkbox"> I have reviewed the example plan details.</label><div class="space-top">${button('Continue to my registry','activate-offer','primary')}</div><p class="note-inline">Interactive design only. This does not subscribe, charge, change a plan or accept real terms.</p></div></div>`;}
function onboarding(){return hero('Let’s start with your products','Choose how to build your registry. You can add evidence later, where it is needed.')+`<div class="form-layout"><div class="stack">${[['add','box','Add a product','Start with a name, classification and website.'],['import','upload','Import a catalog','Bring product records from a CSV file.'],['scan','globe','Scan your website','Discover product records from an authorized website.']].map(([id,i,t,d])=>`<button class="choice ${state.catalogMethod===id?'selected':''}" data-action="choose-method" data-method="${id}">${icon(i)}<div><h3>${t}</h3><p>${d}</p></div></button>`).join('')}<div class="row">${button('Continue','onboard-continue','primary')}${button('I’ll add products later','go-overview','text')}</div></div><div class="side-summary"><span class="overline">Your first steps</span><ol class="steps"><li><span class="step-circle">1</span><div>Record your products<p>Start with facts you already have.</p></div></li><li><span class="step-circle">2</span><div>Review applicability<p>See which policies and evidence apply to each product.</p></div></li><li><span class="step-circle">3</span><div>Resolve requested information<p>Labels, documents or MyCOA lab reports where relevant.</p></div></li></ol><hr class="divider"><p>No products yet? Your workspace can stay empty until your catalog is ready. No COA upload is required to get started.</p></div></div>`;}
function inviteEmail(){return `<div class="email-stage"><div class="email"><div class="email-top">Qredible <span class="subtle">/ Q-Registry invitation</span></div><div class="email-body"><span class="overline">Preview Processing Co. invited your company</span><h1>A registry for every product.<br>Evidence where it matters.</h1><p>You’re invited to Q-Registry, your workspace to register products, review applicable policies and respond to requests for information.</p><ul class="check-list"><li>Start with your product catalog</li><li>See what each product needs</li><li>Use MyCOA when lab evidence is relevant</li></ul><p>Your company does not need a COA for every product to use Registry. Applicable policies determine what evidence is required.</p>${link('Review your Registry access →','offer','button')}<p class="tiny">Already have a Qredible account? Use your existing login to continue with the right company.</p><div class="status-box"><strong>About MyCOA</strong><p>MyCOA is the lab-evidence capability within Q-Registry. Your offer explains which tools are included.</p></div></div><div class="email-foot">Proposed invitation wording · no real invitation or account link is generated by this prototype.</div></div></div>`;}
function subscription(){return hero('Subscription & features','Your Registry access and the tools included in your plan.',button('Review capability model','go-capabilities'))+`<div class="grid main-side"><div class="stack"><div class="card card-pad"><div class="row between"><span class="overline">Current plan · illustrative record</span>${pill('Active','blue')}</div><h2 style="font-size:24px;margin-top:13px">Q-Registry membership</h2><div class="price">$199<small> / month</small></div><p class="tiny subtle">Existing example price · current financial terms preserved</p><hr class="divider"><div class="facts"><div class="fact"><span>Billing period</span><strong>Monthly</strong></div><div class="fact"><span>Next billing</span><strong>November 5, 2026 · example</strong></div></div></div>${card('Included capabilities',`<div class="card-pad">${[['Product registry','Catalog, product facts and website scope','Included'],['Policy assessments & tasks','Scoped findings and information requests','Included'],['Required-evidence submission','Authorized product evidence remediation','Included'],['MyCOA lab tools','Broader lab-report library and management',state.tools==='included'?'Included':'Not included']].map(([a,b,c])=>`<div class="feature-row"><div><strong>${a}</strong><p>${b}</p></div>${pill(c,c==='Included'?'blue':'')}</div>`).join('')}</div>`)}</div><div class="stack"><div class="card card-pad"><h3>One product, different capabilities</h3><p class="small subtle">Registry gives your team a workspace for all products. MyCOA adds lab-evidence tools where included. Plan access does not change what a product policy requires.</p>${link('View your evidence tasks →','evidence','small')}</div><div class="card card-pad"><h3>Later capabilities</h3><p class="small subtle">Product records, Q-Registered stamps and shipping information are proposed later releases, with their own authority and rollout decisions.</p>${pill('Packaging to confirm','purple')}</div></div></div>`;}
function processor(){return hero('Merchant registry workspace','Enrollment, catalog readiness and product tasks—shown separately.',button('Invite to Q-Registry','go-invite-compose','primary'))+`<div class="stats"><div class="stat"><span class="label">Assigned merchants</span><strong>4</strong><small>Illustrative merchant portfolio</small></div><div class="stat"><span class="label">Registry access active</span><strong>3</strong><small>Subscription / enrollment state</small></div><div class="stat"><span class="label">Awaiting enrollment</span><strong>1</strong><small>Invitation or plan action</small></div><div class="stat"><span class="label">Merchant tasks</span><strong>4</strong><small>Facts, evidence and review</small></div></div><div class="card"><div class="table-toolbar"><strong class="small">Registry merchants</strong><span style="margin-left:auto">${pill('All portfolio states')}</span></div><div class="table-wrap"><table><thead><tr><th>MERCHANT</th><th>ACCOUNT</th><th>REGISTRY ACCESS</th><th>CATALOG</th><th>PRODUCT TASKS</th><th></th></tr></thead><tbody>${[['Everyday Goods Co.','Joined','Active','2 products','Product label requested','no-coa'],['Botanical Goods Co.','Joined','Active','2 products','2 lab reports requested','required'],['Preview Goods Co.','Joined','Active','3 products','Classification + evidence','mixed'],['New Merchant Co.','Invited','Not enrolled','Not supplied','Awaiting catalog','empty']].map(([a,b,c,d,e,s])=>`<tr><td><strong>${a}</strong><p>Preview merchant · sample record</p></td><td>${pill(b,b==='Joined'?'':'purple')}</td><td>${pill(c,c==='Active'?'blue':'')}</td><td>${d}</td><td>${e}</td><td>${button('Open workspace','open-merchant','',`data-scenario="${s}"`)}</td></tr>`).join('')}</tbody></table></div></div><p class="note-inline">Registry access is a commercial/enrollment state. Product assessments, evidence tasks and processor determinations remain separate.</p>`;}
function inviteCompose(){return hero('Invite to Q-Registry','Review the recipient, Registry offer and available tools before sending.',button('Preview invitation email','go-invite-email'))+`<div class="form-layout"><div class="card card-pad"><h2>Merchant invitation</h2><div class="form-stack space-top"><label>Company <input id="invite-company" value="New Merchant Co." required></label><label>Recipient email <input id="invite-email" type="email" value="${h(state.draftRecipient)}" required></label><label>Account path <select id="invite-path"><option>New account invitation</option><option>Existing login · add company</option><option>Existing company · Registry activation</option></select></label><label>Registry offer <select><option>Existing merchant offer · $199 / month (illustrative)</option></select></label></div><hr class="divider"><label class="switch"><input type="checkbox" checked disabled> Invite to Q-Registry product enrollment</label><p class="small subtle">MyCOA is a lab-evidence feature in the offer, not a requirement that this company have COAs.</p><div class="row space-top">${button('Review invitation','review-invite','primary')}${button('Preview email','go-invite-email')}</div></div><div class="side-summary"><h3>What the merchant sees</h3><ol class="steps"><li><span class="step-circle">1</span><div>Invitation to Q-Registry<p>Products and applicable evidence lead.</p></div></li><li><span class="step-circle">2</span><div>Existing account / offer<p>Correct company and commercial context.</p></div></li><li><span class="step-circle">3</span><div>Product-first workspace<p>Usable with a catalog, or no products yet.</p></div></li></ol><hr class="divider"><div class="list-line"><span>Registry product</span>${pill('Enrollment')}</div><div class="list-line"><span>MyCOA lab tools</span>${pill(state.tools==='included'?'Included':'Not included','purple')}</div><p class="note-inline">Recipient validation and email template compatibility are implementation requirements. This is an interactive design proposal.</p></div></div>`;}
function capabilities(){return hero('Registry Core & optional capabilities','Review the proposed product model. This is a design configurator, not Q-Config.')+`<div class="grid three">${[['box','Registry Core','The product workspace',['Product registry and product facts','Policy assessment display and tasks','Authorized required-evidence submission','Company / website permissions'],'Base experience'],['flask','MyCOA','Lab-evidence capability',['Broader report library and matching','Report history and management','Existing certificate publication tools','Included or optional by package'],state.tools==='included'?'Included in review scenario':'Not included in review scenario'],['globe','Product records & stamps','Later public capability',['Explicit product publication','Approved policy-result disclosure','Q-Registered product-page links','Freshness, withdrawal and revocation'],'Later release']].map(([i,t,d,items,b])=>`<div class="card card-pad"><div class="task-icon">${icon(i)}</div><h2 style="margin-top:16px">${t}</h2><p class="small subtle">${d}</p><ul class="check-list">${items.map(x=>`<li>${x}</li>`).join('')}</ul>${pill(b,t==='Registry Core'?'blue':'purple')}</div>`).join('')}</div><div class="card card-pad space-top"><h2>Try the capability boundary</h2><p class="small subtle">Use “MyCOA lab tools” above to turn the broader library off. Products, assessments and required-evidence tasks remain available.</p><div class="row space-top">${button('Open required-evidence tasks','go-evidence','primary')}${button('Open MyCOA feature','go-mycoa')}</div><hr class="divider"><p class="small subtle">No new add-on price or production entitlement is approved by this model. Preserve existing subscriptions and financial terms while owners decide the commercial mapping.</p></div>`;}
function shipping(){const p=current();return hero('Shipping information','A future product- and destination-specific assessment, separate from registration.')+(!p?empty():`<div class="grid main-side"><div class="card card-pad"><h2>Assess a product and destination</h2><div class="form-stack space-top"><label>Product ${selectedProductControl()}</label><div class="form-row"><label>Country <select><option>United States</option></select></label><label>State / destination <select id="destination"><option value="">Choose a destination</option>${['California','New York','Texas'].map(x=>`<option ${state.destination===x?'selected':''}>${x}</option>`).join('')}</select></label></div><label>Assessment context <select><option>Product / website / destination</option></select></label></div><div class="space-top">${button('Request scoped assessment','request-shipping','primary')}</div></div><div class="card card-pad"><span class="overline">Destination assessment</span><h2 style="margin-top:15px">Not assessed</h2><p class="small subtle">${state.destination?h(state.destination)+' has been selected. No authoritative policy assessment exists in this prototype.':'Select a destination to define the proposed assessment scope.'}</p><hr class="divider"><div class="list-line"><span>Product</span><strong>${h(p.name)}</strong></div><div class="list-line"><span>Policy / version</span><span>Not selected</span></div><div class="list-line"><span>Shipping permission</span><span>Not determined</span></div><div class="status-box space-top"><p>A registration mark, subscription or lab report does not authorize shipment. Commerce enforcement requires a separate integration.</p></div></div></div>`);}
const renderers={overview,products:catalog,product,assessments,evidence,mycoa,requests,sharing,stamp:stampPage,public:publicRecord,offer,onboarding,'invite-email':inviteEmail,subscription,processor,'invite-compose':inviteCompose,capabilities,shipping};
function render(){const v=V.find(x=>x.id===state.screen)||V[0];if(!current()&&products().length)state.selected=products()[0].id;$('application').innerHTML=['public','invite-email'].includes(state.screen)?renderers[state.screen]():shell(renderers[state.screen]());$('screen-picker').value=state.screen;$('scenario').value=state.scenario;$('lab-tools').value=state.tools;$('phase-label').textContent=v.phase;$('previous').disabled=V.indexOf(v)===0;$('next').disabled=V.indexOf(v)===V.length-1;$('note-title').textContent=v.headline;$('note-summary').textContent=v.summary;$('note-decision').textContent=v.decision;$('note-points').replaceChildren(...v.points.map(t=>{const li=document.createElement('li');li.textContent=t;return li;}));$('design-notes').hidden=!state.notes;$('review-notes').setAttribute('aria-pressed',String(state.notes));history.replaceState(null,'',`#screen=${state.screen}&scenario=${state.scenario}&product=${encodeURIComponent(current()?.id||'')}&tools=${state.tools}`);document.title='Q-Registry · '+v.title;}
function go(screen,pid){if(!renderers[screen])return;if(pid)state.selected=pid;state.screen=screen;state.query='';state.filter='all';render();window.scrollTo(0,0);}
function notify(text){$('notification').textContent=text;$('notification').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('notification').classList.remove('show'),3800);}
function modal(title,body,footer=''){$('modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button data-action="close-modal" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}`;$('modal').showModal();}
function closeModal(){$('modal').close();}
function addProduct(edit=false){const p=edit?current():null;if(edit&&!p)return;modal(edit?'Edit product facts':'Add a product',`<form id="product-form" class="form-stack"><label>Product name <input name="name" required value="${h(p?.name||'')}" placeholder="Your product name"></label><div class="form-row"><label>SKU <input name="sku" value="${h(p?.sku||'')}" placeholder="Optional SKU"></label><label>Classification <input name="category" value="${h(p?.category==='Not classified'?'':p?.category||'')}" placeholder="Record the product category"></label></div><label>Website <input name="site" value="${h(p?.site||'everyday.example.test')}"></label><label>Description <textarea name="description" rows="3">${h(p?.description||'')}</textarea></label><p class="tiny subtle">Evidence applicability will be determined through the relevant policy assessment. Saving facts does not produce a passing result.</p><button class="primary" type="submit">${edit?'Save product facts':'Create product record'}</button></form>`);$('product-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),value={name:String(d.get('name')).trim(),sku:String(d.get('sku')).trim()||'NEW-'+(products().length+1),category:String(d.get('category')).trim()||'Not classified',site:String(d.get('site')).trim(),description:String(d.get('description')).trim()};if(!value.name)return;if(p){Object.assign(p,value);if(p.coa==='unknown')p.reason='Classification submitted for review';}else{const id='new-'+Date.now(),item={...value,id,coa:'unknown',status:'Needs review',reason:'Confirm policy applicability',type:'Classification',task:'Review product facts'};state.extras[state.scenario].push(item);state.selected=id;}closeModal();go('product');notify(edit?'Product facts saved in this design prototype.':'Product record created in this design prototype.');};}
function attach(p=current()){if(!p){notify('Add a product first.');return;}state.selected=p.id;modal(p.type==='COA'?'Attach required lab report':'Attach product evidence',`<p><strong>${h(p.name)}</strong></p><p>${h(p.task)} · ${h(coaLabel(p))}</p><label>Choose a file <input id="evidence-file" type="file" accept=".pdf,.png,.jpg,.jpeg,.txt"></label><label class="space-top">Note for the reviewer <textarea id="evidence-note" rows="3" placeholder="Describe the evidence you are providing"></textarea></label><p class="note-inline">Prototype only: the filename is used for this session’s demonstration. File contents are not uploaded or persisted.</p>`,button('Cancel','close-modal')+button('Submit for review','submit-evidence','primary'));}
const actions={
 'close-modal':closeModal,'add-product':()=>addProduct(),'edit-product':()=>addProduct(true),'product-task':el=>{if(el.dataset.product)state.selected=el.dataset.product;const p=current();if(!p)return;p.coa==='unknown'?addProduct(true):go('evidence');},
 'attach-evidence':el=>attach(products().find(p=>p.id===el.dataset.product)||current()),'attach-generic':()=>attach(),
 'submit-evidence':()=>{const file=$('evidence-file').files[0];if(!file){notify('Choose an evidence file first.');return;}state.uploads[current().id]=file.name;closeModal();render();notify('Evidence received in the prototype. Assessment remains pending review.');},
 'preview-public':()=>go('public'),
 'publish-product':()=>{const p=current();if(!p)return;if(state.published[p.id]){delete state.published[p.id];render();notify('Product record withdrawn in the prototype only.');return;}modal('Review public product record',`<p><strong>${h(p.name)}</strong></p><div class="status-box"><strong>Product identity + truthful assessment state</strong><p>${h(p.status)} · ${h(coaLabel(p))}. No individual evidence files will be published.</p></div><label class="switch space-top"><input id="publication-consent" type="checkbox"> I have reviewed the public fields for this example.</label><p class="note-inline">Design demonstration only. No public registry, live stamp or publication service is called.</p>`,button('Back','close-modal')+button('Publish example record','confirm-publish','primary'));},
 'confirm-publish':()=>{if(!$('publication-consent').checked){notify('Review and confirm the public fields first.');return;}state.published[current().id]=true;closeModal();render();notify('Example product record published within this prototype only.');},
 'copy-snippet':async()=>{try{await navigator.clipboard.writeText($('embed-snippet').textContent);notify('Example snippet copied. It uses a non-production example endpoint.');}catch{notify('Select and copy the example snippet.');}},
 'activate-offer':()=>{if(!$('offer-consent').checked){notify('Review the example offer details first.');return;}go('onboarding');notify('Continuing the design journey. No charge, subscription or consent was submitted.');},
 'choose-method':el=>{state.catalogMethod=el.dataset.method;render();},'onboard-continue':()=>state.catalogMethod==='add'?addProduct():state.catalogMethod==='import'?actions['import-catalog']():actions['scan-website'](),
 'open-merchant':el=>{state.scenario=el.dataset.scenario;state.selected=products()[0]?.id||'';go('overview');},
 'review-invite':()=>{const email=$('invite-email'),name=$('invite-company');if(!name.reportValidity()||!email.reportValidity())return;state.draftRecipient=email.value;modal('Review Registry invitation',`<div class="list-line"><span>Company</span><strong>${h(name.value)}</strong></div><div class="list-line"><span>Recipient</span><strong>${h(email.value)}</strong></div><div class="list-line"><span>Delivery path</span><strong>${h($('invite-path').value)}</strong></div><div class="list-line"><span>Product</span><strong>Q-Registry</strong></div><div class="list-line"><span>Lab tools</span><span>${state.tools==='included'?'MyCOA included':'Not included'}</span></div><p class="note-inline">This demonstrates review of the proposed invitation. No recipient lookup, invitation or email is sent.</p>`,button('Back','close-modal')+button('Preview merchant email','confirm-invite','primary'));},'confirm-invite':()=>{closeModal();go('invite-email');},
 'filter-labels':()=>modal('Labels & documents',`<p>Product labels and documents appear in Registry evidence, alongside any required lab reports.</p>${products().filter(p=>p.type!=='COA').map(p=>`<div class="list-line"><span>${h(p.name)}</span><strong>${h(p.task)}</strong></div>`).join('')||'<p>No non-lab evidence tasks in this sample catalog.</p>'}`,button('Close','close-modal')),
 'certificate-sharing':()=>modal('MyCOA certificate sharing',`<p>Existing certificate pages and View COAs buttons remain the certificate-specific mode. Their report publication and access rules stay separate from Registry product publication.</p><div class="status-box"><strong>Product record mode</strong><p>Can identify a registered product with zero COAs.</p></div><div class="status-box space-top"><strong>Certificate mode · MyCOA</strong><p>Shares individually published lab reports under existing controls.</p></div>`,button('Return to product sharing','close-modal')),
 'open-request':el=>{state.selected=el.dataset.product;const p=current();modal('Product information request',`<p><strong>${h(p.name)}</strong> · ${h(p.task)}</p><div class="status-box"><p>${h(p.reason)}. Please provide the missing information so the assessment can continue.</p></div><label class="space-top">Your response <textarea id="request-response" rows="4" placeholder="Provide context or ask for clarification"></textarea></label><p class="tiny subtle">Responding does not automatically approve the product or publish private case information.</p>`,button('Cancel','close-modal')+button('Submit response','submit-response','primary'));},
 'submit-response':()=>{const text=$('request-response').value.trim();if(!text){notify('Add a response first.');return;}state.responses[current().id]=text;closeModal();render();notify('Response recorded in the prototype; awaiting review.');},
 'ask-question':()=>modal('Ask about a product review',`<label>Your question <textarea rows="4" id="general-question" placeholder="What would you like to clarify?"></textarea></label>`,button('Close','close-modal')+button('Record question','record-question','primary')),
 'record-question':()=>{if(!$('general-question').value.trim()){notify('Add a question first.');return;}closeModal();notify('Question recorded in this design demonstration only.');},
 'import-catalog':()=>modal('Import product records',`<p>Choose a CSV whose first column contains product names. This demonstration reads names locally; nothing is uploaded.</p><label>Catalog CSV <input id="catalog-file" type="file" accept=".csv"></label>`,button('Cancel','close-modal')+button('Import example records','confirm-import','primary')),
 'confirm-import':async()=>{const f=$('catalog-file').files[0];if(!f){notify('Choose a CSV first.');return;}const rows=(await f.text()).split(/\r?\n/).filter(Boolean).map(v=>v.split(',')[0].trim().replace(/^"|"$/g,'')).filter(v=>v&&!/^(name|product|product name)$/i.test(v)).slice(0,20);if(!rows.length){notify('No product names found.');return;}rows.forEach((name,i)=>state.extras[state.scenario].push({id:'import-'+Date.now()+'-'+i,name,sku:'IMP-'+(i+1),category:'Not classified',coa:'unknown',status:'Needs review',reason:'Confirm policy applicability',description:'Imported product facts in the prototype.',site:'everyday.example.test',type:'Classification',task:'Review imported product facts'}));closeModal();go('products');notify(rows.length+' example product records added locally. No policy result was created.');},
 'scan-website':()=>modal('Discover products from your website',`<label>Authorized website <input id="scan-url" type="url" placeholder="https://your-store.example"></label><p class="note-inline">Proposed scan entry. This prototype does not crawl a site or call a scan worker.</p>`,button('Cancel','close-modal')+button('Review scan request','review-scan','primary')),
 'review-scan':()=>{const u=$('scan-url');if(!u.reportValidity()||!u.value){notify('Enter a website URL first.');return;}closeModal();notify('Scan request previewed. No website was fetched or scan queued.');},
 'request-shipping':()=>{if(!state.destination){notify('Choose a destination first.');return;}modal('Scoped shipping assessment',`<p><strong>${h(current().name)}</strong> · ${h(state.destination)}</p><div class="status-box"><strong>Not assessed</strong><p>A real evaluation needs authoritative policy, product/variant/batch, date and commerce context. This design cannot grant shipping permission.</p></div>`,button('Close','close-modal'));},
 'company':()=>modal('Company workspace',`<p><strong>${h(company())}</strong></p><p>Product and evidence access stay scoped to the selected company and its authorized websites.</p>`,button('Close','close-modal')),
 'info':()=>info()
};
function info(){modal('About the new Q-Registry design',`<p>This is the <strong>proposed new product experience</strong>, using the existing platform’s navigation, colors and table conventions. It replaces the screenshot audit as the primary experience.</p><p><strong>Q-Registry is the product. MyCOA is its lab-evidence capability.</strong> Explore all 18 proposed views, switch merchant scenarios and turn MyCOA tools off to review the proposed commercial boundary.</p><ul><li>All records, evidence requests and assessment displays are illustrative, not real policy determinations.</li><li>Interactions run only in this browser’s memory. No authentication, payment, email, production API, policy activation, publication or shipping service is called.</li><li>Core, commercial packaging, names and public mark meaning require approval. Public records/stamps and shipping are labeled later/future views.</li><li>These are rendered design interfaces, not screenshots or deployed product acceptance.</li></ul><p>${link('Open Registry overview','overview')} · <a href="reference.html">Earlier screenshot/source audit</a> · <a href="https://qredible.atlassian.net/browse/QP-5004" target="_blank" rel="noopener">QP-5004</a></p>`,button('Continue exploring','close-modal'));}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-go]');if(nav){e.preventDefault();closeModal();go(nav.dataset.go,nav.dataset.product);return;}const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(a.startsWith('go-')){closeModal();go(a.slice(3));return;}if(el.dataset.product)state.selected=el.dataset.product;actions[a]?.(el);});
document.addEventListener('change',e=>{if(e.target.id==='product-choice'){state.selected=e.target.value;render();}if(e.target.id==='product-filter'){state.filter=e.target.value;render();}if(e.target.id==='stamp-style'){state.stampStyle=e.target.value;render();}if(e.target.id==='destination'){state.destination=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='product-search'){state.query=e.target.value;const selection=e.target.selectionStart;const wrap=document.querySelector('.table-wrap');const footer=document.querySelector('.table-foot');const temp=document.createElement('div');temp.innerHTML=productRows();wrap.replaceWith(temp.querySelector('.table-wrap'));footer.replaceWith(temp.querySelector('.table-foot'));e.target.focus();e.target.setSelectionRange(selection,selection);}});
$('screen-picker').replaceChildren(...V.map((v,i)=>new Option(String(i+1).padStart(2,'0')+' · '+v.title,v.id)));
$('screen-picker').onchange=e=>go(e.target.value);$('scenario').onchange=e=>{state.scenario=e.target.value;state.selected=products()[0]?.id||'';render();};$('lab-tools').onchange=e=>{state.tools=e.target.value;render();};$('previous').onclick=()=>go(V[V.findIndex(v=>v.id===state.screen)-1]?.id);$('next').onclick=()=>go(V[V.findIndex(v=>v.id===state.screen)+1]?.id);$('review-notes').onclick=()=>{state.notes=!state.notes;render();};$('design-info').onclick=info;$('share-design').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);notify('Link to this proposed screen copied.');}catch{notify('Copy the address to share this proposed screen.');}};
document.addEventListener('keydown',e=>{if($('modal').open||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='ArrowRight')$('next').click();if(e.key==='ArrowLeft')$('previous').click();});
const initial=new URLSearchParams(location.hash.slice(1));if(renderers[initial.get('screen')])state.screen=initial.get('screen');if(['mixed','no-coa','required','empty'].includes(initial.get('scenario')))state.scenario=initial.get('scenario');if(initial.get('tools')==='not-included')state.tools='not-included';state.selected=initial.get('product')||products()[0]?.id||'';
window.REGISTRY_DESIGN={views:V.map(({id,title,actor,phase})=>({id,title,actor,phase})),boundary:'Interactive design proposal, illustrative data and browser-memory interactions only; no deployed product acceptance'};render();
